def sample_and_write_to_txt(data, n=50, output_file="sampled_data.txt"):
    """
    从原始数据中随机采样n行，并以相同格式写入txt文件
    
    Args:
        data: 原始数据列表
        n: 要采样的行数
        output_file: 输出文件名
    """
    # 确保采样数量不超过数据总量
    n = min(n, len(data))
    
    # 随机采样
    sampled_data = random.sample(data, n)
    
    # 写入文件，保持原始格式
    with open(output_file, 'w', encoding='utf-8') as f:
        f.write('sample_data_raw = [\n')
        
        # 写入每一行数据
        for i, item in enumerate(sampled_data):
            # 将列表转换为字符串表示
            line_str = '    ['
            line_str += ', '.join([f"'{element}'" for element in item])
            line_str += ']'
            
            # 如果不是最后一行，添加逗号
            if i < len(sampled_data) - 1:
                line_str += ','
            
            f.write(line_str + '\n')
        
        f.write(']')
    
    print(f"成功采样 {n} 行数据并保存到 {output_file}")
    print(f"原始数据行数: {len(data)}")
    print(f"采样数据行数: {len(sampled_data)}")

# 使用示例
if __name__ == "__main__":
    # 确保你的sample_data_raw至少包含50行数据
    if len(sample_data_raw) >= 50:
        sample_and_write_to_txt(sample_data_raw, n=50, output_file="sampled_data.txt")
        
        # 可选：显示采样的数据
        print("\n采样的数据示例（前2行）:")
        sampled_data = random.sample(sample_data_raw, min(2, len(sample_data_raw)))
        for i, item in enumerate(sampled_data):
            print(f"第{i+1}行: {item[:3]}...")  # 只显示前3个字段
    else:
        print(f"错误：原始数据只有 {len(sample_data_raw)} 行，需要至少50行才能采样。")